<div class="bearly-chat-backdrop" data-bearly-chat-close hidden></div>
<aside class="bearly-chat-drawer" data-bearly-chat-drawer aria-hidden="true" aria-label="Bearly chat">
<header class="bearly-chat-drawer-head"><div><span class="bearly-chat-kicker">Buyer messages</span><h2>Chat</h2></div><div class="bearly-chat-head-actions"><a href="{{ url('/chat') }}" class="bearly-chat-expand" aria-label="Open full chat"><span class="material-symbols-outlined">open_in_full</span></a><button type="button" data-bearly-chat-close aria-label="Close chat"><span class="material-symbols-outlined">close</span></button></div></header>
<div class="bearly-chat-compact" data-bearly-chat-root data-chat-mode="compact"><div class="bearly-chat-list" data-chat-list></div><section class="bearly-chat-thread"><div class="bearly-chat-thread-head" data-chat-thread-head></div><div class="bearly-chat-messages" data-chat-messages></div><div class="bearly-chat-quick" data-chat-quick></div><form class="bearly-chat-composer" data-chat-form><input type="text" data-chat-input placeholder="Write a message..." autocomplete="off" maxlength="240"><button type="submit" aria-label="Send message"><span class="material-symbols-outlined">send</span></button></form></section></div>
</aside>
